Here is the commit message:
ethtool: netlink: do not return SQI value if link is down

Do not attach SQI value if link is down. "SQI values are only valid if
link-up condition is present" per OpenAlliance specification of
100Base-T1 Interoperability Test suite [1]. The same rule would apply
for other link types.

[1] https://opensig.org/automotive-ethernet-specifications/#

Fixes: 806602191592 ("ethtool: provide UAPI for PHY Signal Quality Index (SQI)")
Signed-off-by: Oleksij Rempel <o.rempel@pengutronix.de>
Reviewed-by: Andrew Lunn <andrew@lunn.ch>
Reviewed-by: Woojung Huh <woojung.huh@microchip.com>
Link: https://patch.msgid.link/20240709061943.729381-1-o.rempel@pengutronix.de
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The bug arises from the fact that the Signal Quality Index (SQI) values were being returned even when the network link was down. According to the OpenAlliance specification, SQI values are only valid when the link is active. The absence of checks to ensure the link state before retrieving and returning SQI values led to the potential for invalid data being communicated, which could mislead users or systems relying on accurate link quality information.

Here is the patch:

 static int linkstate_get_sqi(struct net_device *dev)
 {
 	struct phy_device *phydev = dev->phydev;
 	int ret;

 	if (!phydev)
 		return -EOPNOTSUPP;

 	mutex_lock(&phydev->lock);
 	if (!phydev->drv || !phydev->drv->get_sqi)
 		ret = -EOPNOTSUPP;
+	else if (!phydev->link)
+		ret = -ENETDOWN;
 	else
 		ret = phydev->drv->get_sqi(phydev);
 	mutex_unlock(&phydev->lock);

 	return ret;
 }

 static int linkstate_get_sqi_max(struct net_device *dev)
 {
 	struct phy_device *phydev = dev->phydev;
 	int ret;

 	if (!phydev)
 		return -EOPNOTSUPP;

 	mutex_lock(&phydev->lock);
 	if (!phydev->drv || !phydev->drv->get_sqi_max)
 		ret = -EOPNOTSUPP;
+	else if (!phydev->link)
+		ret = -ENETDOWN;
 	else
 		ret = phydev->drv->get_sqi_max(phydev);
 	mutex_unlock(&phydev->lock);

 	return ret;
 };

+static bool linkstate_sqi_critical_error(int sqi)
+{
+	return sqi < 0 && sqi != -EOPNOTSUPP && sqi != -ENETDOWN;
+}
+
+static bool linkstate_sqi_valid(struct linkstate_reply_data *data)
+{
+	return data->sqi >= 0 && data->sqi_max >= 0 &&
+	       data->sqi <= data->sqi_max;
+}
+
 static int linkstate_get_link_ext_state(struct net_device *dev,
 					struct linkstate_reply_data *data)
 {
 	int err;

 	if (!dev->ethtool_ops->get_link_ext_state)
 		return -EOPNOTSUPP;

 	err = dev->ethtool_ops->get_link_ext_state(dev, &data->ethtool_link_ext_state_info);
 	if (err)
 		return err;

 	data->link_ext_state_provided = true;

 	return 0;
 }

 static int linkstate_prepare_data(const struct ethnl_req_info *req_base,
 				  struct ethnl_reply_data *reply_base,
 				  const struct genl_info *info)
 {
 	struct linkstate_reply_data *data = LINKSTATE_REPDATA(reply_base);
 	struct net_device *dev = reply_base->dev;
 	int ret;

 	ret = ethnl_ops_begin(dev);
 	if (ret < 0)
 		return ret;
 	data->link = __ethtool_get_link(dev);

 	ret = linkstate_get_sqi(dev);
-	if (ret < 0 && ret != -EOPNOTSUPP)
+	if (linkstate_sqi_critical_error(ret))
 		goto out;
 	data->sqi = ret;

 	ret = linkstate_get_sqi_max(dev);
-	if (ret < 0 && ret != -EOPNOTSUPP)
+	if (linkstate_sqi_critical_error(ret))
 		goto out;
 	data->sqi_max = ret;

 	if (dev->flags & IFF_UP) {
 		ret = linkstate_get_link_ext_state(dev, data);
 		if (ret < 0 && ret != -EOPNOTSUPP && ret != -ENODATA)
 			goto out;
 	}

 	ethtool_stats_init((u64 *)&data->link_stats,
 			   sizeof(data->link_stats) / 8);

 	if (req_base->flags & ETHTOOL_FLAG_STATS) {
 		if (dev->phydev)
 			data->link_stats.link_down_events =
 				READ_ONCE(dev->phydev->link_down_events);

 		if (dev->ethtool_ops->get_link_ext_stats)
 			dev->ethtool_ops->get_link_ext_stats(dev,
 							     &data->link_stats);
 	}

 	ret = 0;
 out:
 	ethnl_ops_complete(dev);
 	return ret;
 }

 static int linkstate_reply_size(const struct ethnl_req_info *req_base,
 				const struct ethnl_reply_data *reply_base)
 {
 	struct linkstate_reply_data *data = LINKSTATE_REPDATA(reply_base);
 	int len;

 	len = nla_total_size(sizeof(u8)) /* LINKSTATE_LINK */
 		+ 0;

-	if (data->sqi != -EOPNOTSUPP)
-		len += nla_total_size(sizeof(u32));
-
-	if (data->sqi_max != -EOPNOTSUPP)
-		len += nla_total_size(sizeof(u32));
+	if (linkstate_sqi_valid(data)) {
+		len += nla_total_size(sizeof(u32)); /* LINKSTATE_SQI */
+		len += nla_total_size(sizeof(u32)); /* LINKSTATE_SQI_MAX */
+	}

 	if (data->link_ext_state_provided)
 		len += nla_total_size(sizeof(u8)); /* LINKSTATE_EXT_STATE */

 	if (data->ethtool_link_ext_state_info.__link_ext_substate)
 		len += nla_total_size(sizeof(u8)); /* LINKSTATE_EXT_SUBSTATE */

 	if (data->link_stats.link_down_events != ETHTOOL_STAT_NOT_SET)
 		len += nla_total_size(sizeof(u32));

 	return len;
 }

 static int linkstate_fill_reply(struct sk_buff *skb,
 				const struct ethnl_req_info *req_base,
 				const struct ethnl_reply_data *reply_base)
 {
 	struct linkstate_reply_data *data = LINKSTATE_REPDATA(reply_base);

 	if (data->link >= 0 &&
 	    nla_put_u8(skb, ETHTOOL_A_LINKSTATE_LINK, !!data->link))
 		return -EMSGSIZE;

-	if (data->sqi != -EOPNOTSUPP &&
-	    nla_put_u32(skb, ETHTOOL_A_LINKSTATE_SQI, data->sqi))
-		return -EMSGSIZE;
+	if (linkstate_sqi_valid(data)) {
+		if (nla_put_u32(skb, ETHTOOL_A_LINKSTATE_SQI, data->sqi))
+			return -EMSGSIZE;

-	if (data->sqi_max != -EOPNOTSUPP &&
-	    nla_put_u32(skb, ETHTOOL_A_LINKSTATE_SQI_MAX, data->sqi_max))
-		return -EMSGSIZE;
+		if (nla_put_u32(skb, ETHTOOL_A_LINKSTATE_SQI_MAX,
+				data->sqi_max))
+			return -EMSGSIZE;
+	}

 	if (data->link_ext_state_provided) {
 		if (nla_put_u8(skb, ETHTOOL_A_LINKSTATE_EXT_STATE,
 			       data->ethtool_link_ext_state_info.link_ext_state))
 			return -EMSGSIZE;

 		if (data->ethtool_link_ext_state_info.__link_ext_substate &&
 		    nla_put_u8(skb, ETHTOOL_A_LINKSTATE_EXT_SUBSTATE,
 			       data->ethtool_link_ext_state_info.__link_ext_substate))
 			return -EMSGSIZE;
 	}

 	if (data->link_stats.link_down_events != ETHTOOL_STAT_NOT_SET)
 		if (nla_put_u32(skb, ETHTOOL_A_LINKSTATE_EXT_DOWN_CNT,
 				data->link_stats.link_down_events))
 			return -EMSGSIZE;

 	return 0;
 }



